#include "professional_order_contract.hpp"
#include "resident/storage/common_store.hpp"
namespace hanmo::resident {namespace {
bool source(const SourceRef&r){return !r.domain.empty()&&!r.kind.empty()&&!r.id.empty();}
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
bool criterion(const ProfessionalCriterion&c){return !c.criterion_kind.empty()&&!c.criterion_version.empty();}
Status job(const OrderedProfessionalJobRef&ref){return std::visit([](const auto&v){using T=std::decay_t<decltype(v)>;bool valid=false;if constexpr(std::is_same_v<T,OrderedCopyJob>)valid=source(v.copy_activity_ref);else if constexpr(std::is_same_v<T,OrderedInfusionJob>)valid=!v.job_id.empty();else valid=!v.service_id.empty()&&static_cast<Integer>(v.kind)>=0&&static_cast<Integer>(v.kind)<=2;return valid?common_success():common_failure("InvalidOrderedProfessionalJob");},ref);}
}
Status validate_order_service_acceptance_key(const OrderServiceAcceptanceKey&v){if(v.order_id.empty()||v.line_id.empty())return common_failure("InvalidOrderServiceAcceptanceKey");return validate_terms_revision(v.first_accepted_terms_ref);}
bool same_order_service_acceptance_key(const OrderServiceAcceptanceKey&a,const OrderServiceAcceptanceKey&b){return a.order_id==b.order_id&&a.line_id==b.line_id&&same_terms_revision(a.first_accepted_terms_ref,b.first_accepted_terms_ref);}
bool same_ordered_professional_job(const OrderedProfessionalJobRef&a,const OrderedProfessionalJobRef&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&v){using T=std::decay_t<decltype(v)>;const auto&w=std::get<T>(b);if constexpr(std::is_same_v<T,OrderedCopyJob>)return same(v.copy_activity_ref,w.copy_activity_ref);else if constexpr(std::is_same_v<T,OrderedInfusionJob>)return v.job_id==w.job_id;else return v.service_id==w.service_id&&v.kind==w.kind;},a);}
Outcome<ProfessionalOutcomeKind> ordered_professional_completion_kind(const OrderedProfessionalJobRef&v){auto valid=job(v);if(!valid.ok)return {false,{},valid.error};return {true,std::visit([](const auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,OrderedCopyJob>)return ProfessionalOutcomeKind::copy_completed;else if constexpr(std::is_same_v<T,OrderedInfusionJob>)return ProfessionalOutcomeKind::infusion_completed;else return x.kind==OrderedArcaneKind::recharge?ProfessionalOutcomeKind::recharge_completed:x.kind==OrderedArcaneKind::effect_maintenance?ProfessionalOutcomeKind::effect_maintenance_completed:ProfessionalOutcomeKind::arcane_appraisal_completed;},v),{}};}
Status validate_ordered_professional_binding_shape(const OrderedProfessionalBinding&v){
 auto valid=validate_order_service_acceptance_key(v.acceptance_key);if(!valid.ok)return valid;valid=job(v.job);if(!valid.ok)return valid;valid=validate_terms_revision(v.professional_terms_ref);if(!valid.ok)return valid;
 if(!criterion(v.accepted_criterion)||v.fee_rule!=OrderedCompletionFeeRule::ordered_professional_completion_v1||!source(v.fee_terms_ref)||!source(v.continuity_terms_ref)||v.accepted_follow_through.size()>64)return common_failure("InvalidOrderedProfessionalBinding");
 if(const auto*r=std::get_if<OrderedOriginalReworkClause>(&v.attempt_rule)){valid=validate_terms_revision(r->terms_ref);if(!valid.ok)return valid;if(r->clause_ordinal<0)return common_failure("InvalidOrderedReworkClause");}
 for(std::size_t n=0;n<v.accepted_follow_through.size();++n){const auto&f=v.accepted_follow_through[n];if(!same_order_service_acceptance_key(f.acceptance_key,v.acceptance_key)||f.obligation_ordinal<0||f.obligation_ordinal>63)return common_failure("InvalidOrderedFollowThrough");for(std::size_t p=0;p<n;++p)if(v.accepted_follow_through[p].obligation_ordinal==f.obligation_ordinal)return common_failure("DuplicateOrderedFollowThrough");
  valid=std::visit([&](const auto&x)->Status{using T=std::decay_t<decltype(x)>;
   if constexpr(std::is_same_v<T,OrderedReturnCustomerInstance>){if(x.item_instance_id.empty()||!source(x.original_custody_terms_ref)||!source(x.recipient_terms_ref))return common_failure("InvalidOrderedCustomerReturn");}
   else if constexpr(std::is_same_v<T,OrderedDeliverProducedCopies>){const auto*copy=std::get_if<OrderedCopyJob>(&v.job);if(!copy||!same(copy->copy_activity_ref,x.copy_activity_ref)||x.required_output_count<1||!source(x.delivery_terms_ref))return common_failure("InvalidOrderedCopyDelivery");}
   else if(!same_ordered_professional_job(v.job,x.job)||!source(x.recipient_terms_ref)||!source(x.disclosure_terms_ref))return common_failure("InvalidOrderedResultDelivery");
   return common_success();
  },f.kind);if(!valid.ok)return valid;
 }
 return common_success();
}
Status validate_ordered_execution_member_shape(const OrderedProfessionalExecutionMember&v){auto valid=validate_order_service_acceptance_key(v.acceptance_key);if(!valid.ok)return valid;valid=job(v.job);if(!valid.ok)return valid;valid=validate_terms_revision(v.professional_terms_ref);if(!valid.ok)return valid;if(v.execution_ordinal<0||((v.execution_ordinal==0)!=std::holds_alternative<OrderedInitialAcceptance>(v.authority)))return common_failure("InvalidOrderedExecutionOrdinal");if(const auto*r=std::get_if<OrderedReworkAuthority>(&v.authority)){valid=validate_terms_revision(r->terms_ref);if(!valid.ok)return valid;if(r->clause_ordinal<0||r->preceding_execution_ordinal<0||r->preceding_execution_ordinal>=v.execution_ordinal)return common_failure("InvalidOrderedReworkAuthority");}return common_success();}
Status validate_ordered_completion_fee_terms_shape(const OrderedCompletionFeeTerms&v){auto valid=validate_order_service_acceptance_key(v.acceptance_key);if(!valid.ok)return valid;return v.fee_item_ordinal==0&&v.quoted_qian>=0&&criterion(v.criterion)&&source(v.payment_terms_ref)?common_success():common_failure("InvalidOrderedCompletionFeeTerms");}
Status validate_ordered_completion_charge_shape(const OrderedCompletionChargeSource&v){auto valid=validate_order_service_acceptance_key(v.charge_key.acceptance_key);if(!valid.ok)return valid;auto kind=ordered_professional_completion_kind(v.job);if(!kind.ok)return {false,{},kind.error};valid=validate_outcome_fact_ref(v.qualifying_outcome);if(!valid.ok)return valid;if(v.charge_key.fee_item_ordinal!=0||!source(v.fee_terms_ref)||!criterion(v.criterion)||v.earned_qian<0||v.earned_tick<0||v.qualifying_outcome.source_kind!=kind.value)return common_failure("InvalidOrderedCompletionCharge");return common_success();}
}
